import {lines} from './network.mjs';
export const mapSize={width:3000,height:1500};
export const positions={};
function assign(line,coords){if(coords.length!==line.names.length)throw Error('Layout incomplete '+line.id);coords.forEach((p,i)=>{const name=line.names[i];if(positions[name]&&(positions[name][0]!==p[0]||positions[name][1]!==p[1]))throw Error('Disconnected interchange '+name);positions[name]=p;});}
assign(lines[0],[[100,1380],[180,1380],[260,1380],[340,1380],[420,1380],[500,1300],[580,1220],[660,1140],[740,1100],[820,1040],[900,970],[1000,860],[1100,750],[1020,670],[940,590],[940,510],[880,430],[820,350],[760,270],[700,190],[640,110],[560,110],[480,110],[400,110],[320,110],[240,110],[160,110],[80,110]]);
